#include <iostream>

int main()
{
    double weight{};
    int express{};
    std::cin >> weight >> express;

    if (weight <= 0)
    {
        std::cout << "Invalid weight\n";
        return 0;
    }
    if (weight > 20)
    {
        std::cout << "Too heavy\n";
        return 0;
    }

    int cost{};
    if (weight <= 1) cost = 5;
    else if (weight <= 5) cost = 9;
    else cost = 15;

    if (express == 1)
    {
        cost += 7;
    }

    std::cout << "Cost: " << cost << '\n';
    return 0;
}
